    >
      <MessageGroup className="gap-6">
        <Message align="end">
          <MessageContent>
            <Bubble variant="muted">
              <BubbleContent>
                Where is the keyboard shortcut for the command menu defined?
              </BubbleContent>
            </Bubble>
          </MessageContent>
        </Message>
        <Message>
          <MessageContent>
            <MessageHeader>Agent</MessageHeader>
            <Bubble variant="ghost">
              <BubbleContent>
                I’ll check where the command menu registers its shortcut.
              </BubbleContent>
            </Bubble>
            <Marker render={<output />}>
              <MarkerIcon>
                <Icon name="search-01" />
              </MarkerIcon>
              <MarkerContent className="shimmer">Reading project files…</MarkerContent>
            </Marker>
          </MessageContent>
        </Message>
      </MessageGroup>
    </figure>
  );
}
" },
